'use strict';
const v5raw=new Map([DASurveyArea,...areas].map(d=>[d.id,structuredClone(d)]));
const scenarioEdits=new Map();try{for(const entry of JSON.parse(localStorage.getItem('disabledaccess-v5-scenarios')||'[]'))scenarioEdits.set(entry.id,entry);}catch{}
const v4Persist=persist;persist=function(){v4Persist();scenarioEdits.set(state.data.id,{id:state.data.id,barriers:state.data.barriers.filter(b=>b.sourceRecord).map(b=>structuredClone(b)),repairs:state.data.repairs.map(r=>({id:r.id,cost:r.cost}))});try{localStorage.setItem('disabledaccess-v5-scenarios',JSON.stringify([...scenarioEdits.values()]));}catch{notify('Scenario edits could not be saved locally');}};
let evidenceMode='strict',modeComparison=null,applying=null,presentationStep=-1,presentationBusy=false,swipeEnabled=false;
const v4Load=loadArea,v4Render=render,v4Inspector=renderInspector,v4Cancel=cancel,v4RenderMap=renderMap;
const v4SetBusy=setBusy;setBusy=function(value){v4SetBusy(value);if($('compare-modes'))$('compare-modes').disabled=value||!state.data.source||!!state.data.isHypothetical;if($('apply-plan'))$('apply-plan').disabled=value||!state.plan||!!applying;if($('swipe-toggle'))$('swipe-toggle').disabled=value||!state.plan||!state.data.source||renderer!=='geo'||!!applying;};
const modeLabel=()=>((state.data.surveyObservations||[]).some(o=>o.fixture)?'TEST FIXTURE · ':'')+(state.data.evidenceLabel||(state.data.source?'Hypothetical scenario on OSM geometry':'Synthetic planning fixture'));
renderMap=function(){v4RenderMap();const svg=$('svg-map').querySelector('svg'),d=state.data;if(!svg||!d.source)return;const box=d.source.bounds;if(!box)return;const midLon=(box[0]+box[2])/2,midLat=(box[1]+box[3])/2,cos=Math.cos(midLat*Math.PI/180),scale=Math.min(710/((box[2]-box[0])*cos),420/(box[3]-box[1]));for(const o of d.surveyObservations||[]){if(!Number.isFinite(o.lat)||!Number.isFinite(o.lon))continue;const dot=document.createElementNS('http://www.w3.org/2000/svg','circle');dot.setAttribute('cx',410+(o.lon-midLon)*cos*scale);dot.setAttribute('cy',260-(o.lat-midLat)*scale);dot.setAttribute('r','7');dot.setAttribute('class','survey-dot '+o.link.status);dot.setAttribute('tabindex','0');dot.setAttribute('role','button');dot.setAttribute('aria-label',o.type+' · '+o.link.status+' · '+o.provenance);bindClickKey(dot,()=>inspectObservation(o.id));svg.append(dot);}};
function cleanNames(d){if(!d.imported)return d;for(const n of d.nodes)if(/^Point \d+$/.test(n.label))n.label='';for(const n of d.nodes.filter(n=>n.kind==='destination'&&!n.label)){n.label='Planning destination '+(d.nodes.filter(x=>x.kind==='destination').indexOf(n)+1);n.labelProvenance='hypothetical';}DAImporter.destinations(d,d.nodes.filter(n=>n.kind==='destination').map(n=>n.id));return d;}
function mergedArea(id,mode=evidenceMode){const raw=cleanNames(structuredClone(v5raw.get(id)));const merged=raw.source&&!raw.isHypothetical?DASurvey.merge(raw,surveyOverlay(id),mode):raw;const edits=scenarioEdits.get(id);if(edits){for(const b of merged.barriers){const edit=edits.barriers.find(x=>x.id===b.id);if(edit)Object.assign(b,edit);}for(const r of merged.repairs){const edit=edits.repairs.find(x=>x.id===r.id);if(edit&&Number.isSafeInteger(edit.cost)&&edit.cost>=0)r.cost=edit.cost;}}return merged;}
const cityRaw=v5raw.get('city');if(cityRaw){const p=cityRaw.paths.find(p=>p.id==='BRIDGE-CD');p.geometry=[{x:690,y:76},{x:805,y:55},{x:825,y:275},{x:690,y:326}];}
function rebuildAreas(){areas=[...v5raw.keys()].map(id=>mergedArea(id));areaOptions();}
loadArea=function(id){if(!v5raw.has(id)){const found=areas.find(d=>d.id===id);if(found)v5raw.set(id,structuredClone(found));}modeComparison=null;swipeEnabled=false;closeSwipe();areas[areas.findIndex(d=>d.id===id)]=mergedArea(id);v4Load(id);$('map-status').textContent=!state.data.source?'Synthetic schematic':offlineMode?'Offline rehearsal on · bundled schematic':navigator.onLine?'':'Network offline · bundled schematic';if(state.data.source?.bounds)['bbox-w','bbox-s','bbox-e','bbox-n'].forEach((key,i)=>$(key).value=state.data.source.bounds[i]);$('evidence-mode').value=evidenceMode;presentationStep=-1;$('present-status').textContent='';$('evidence-mode').disabled=!state.data.source||!!state.data.isHypothetical;renderSurvey();if(state.data.source&&!offlineMode&&navigator.onLine)rendererMode('geo');};
cancel=function(){applying=null;stopSwipeAnimation();v4Cancel();};
const v4SetView=setView;setView=function(view){swipeEnabled=false;closeSwipe();$('swipe-toggle').setAttribute('aria-pressed','false');v4SetView(view);};
function reloadEvidence(){const id=state.data.id,limit=state.limit,moneyValue=$('money-budget').value,useMoney=state.useMoney;loadArea(id);state.limit=Math.min(limit,state.data.maxRepairLimit);$('repair-limit').value=state.limit;$('limit-value').value=state.limit;$('money-budget').value=moneyValue;state.money=Number(moneyValue);state.useMoney=useMoney;$('use-budget').checked=useMoney;render();}
render=function(){v4Render();if(!$('mode-banner'))return;$('mode-banner').textContent=modeLabel();for(const el of document.querySelectorAll('.analysis-mode'))el.textContent=modeLabel();$('mode-banner').classList.toggle('assumed',state.data.evidenceMode==='assumed');$('retrieval').textContent=state.data.source?`OSM data retrieved: ${state.data.source.retrieved||'date unavailable'} · Last mapped update: ${state.data.source.community?.lastUpdated||'metadata unavailable'} · Area edit count unavailable`: 'Synthetic fixture · no real observations';$('source-strip').innerHTML=state.data.source?`© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a> · ODbL · ${esc(modeLabel())}`:'Synthetic network · illustrative estimates · no field observations.';$('compare-modes').disabled=!state.data.source||!!state.data.isHypothetical||busy;$('apply-plan').disabled=!state.plan||busy||!!applying;$('swipe-toggle').disabled=!state.plan||!state.data.source||renderer!=='geo'||!!applying||busy;$('swipe-toggle').setAttribute('aria-pressed',String(swipeEnabled));$('apply-origin').innerHTML='<option value="">Choose flood origin</option>'+state.data.nodes.filter(n=>n.kind==='destination').map(n=>`<option value="${esc(n.id)}" ${n.id===$('reach-origin').value?'selected':''}>${esc(n.label)}</option>`).join('');$('greedy-main').textContent=state.plan&&state.plan.greedy.newlyConnectedJourneyIds.length!==state.plan.recommended.newlyConnectedJourneyIds.length?`Why these repairs? Greedy: +${state.plan.greedy.newlyConnectedJourneyIds.length} pairs · ${state.plan.optimal?'Optimal combination':'Best found'}: +${state.plan.recommended.newlyConnectedJourneyIds.length} pairs`:'';$('mode-comparison').innerHTML=modeComparison?`<h3>Same constraints. Different evidence.</h3><p>${state.limit} repairs maximum · ${state.useMoney?money(state.money):'no money cap'}</p><div class="comparison">${['strict','assumed'].map(mode=>{const r=modeComparison[mode];return`<div><span>${mode==='strict'?'Strict · recorded only':'Assumption · unknown paths passable'}</span><strong>${r.baseline.connectedCount} → ${r.recommended.connectedCount}</strong><small>${r.recommended.repairIds.length} repairs · ${money(r.recommended.totalCost)} illustrative<br>${r.recommended.repairIds.map(id=>esc(state.data.repairs.find(x=>x.id===id)?.title||'Repair')).join(', ')||'No beneficial plan'}<br>${r.optimal?'Proven optimal within model':'Best found; search capped'}</small></div>`;}).join('')}</div>`:'';if(swipeEnabled)renderSwipe();};
const oldInvalidate=invalidate;invalidate=function(){modeComparison=null;closeSwipe();swipeEnabled=false;presentationStep=-1;$('present-status').textContent='Controls changed — presentation reset';oldInvalidate();};
renderMetrics=function(){const p=active(),b=state.baseline;const previous=Number($('connected-count')?.textContent||b?.connectedCount||0),target=p?.connectedCount||0;$('metrics').innerHTML=`<div class="metric"><label>Connected destination pairs</label><strong>${b?.connectedCount??'—'} → <em id="connected-count">${target}</em></strong><small>of ${state.data.journeys.length} · ${esc(modeLabel())}</small></div><div class="metric"><label>Newly connected</label><strong class="gain">+${p?.newlyConnectedJourneyIds.length||0}</strong><small>destination pairs</small></div><div class="metric"><label>Repairs simulated: ${p?.repairIds.length||0}</label><strong>${money(p?.totalCost||0)}</strong><small>illustrative estimate, not a quotation</small></div>`;if(previous!==target&&!reducedMotion()){const el=$('connected-count'),start=performance.now();function tick(now){if(!el.isConnected)return;const t=Math.min(1,(now-start)/500);el.textContent=Math.round(previous+(target-previous)*t);if(t<1)requestAnimationFrame(tick);}requestAnimationFrame(tick);}};
renderInspector=function(){const d=state.data,p=active();if(inspected){v4Inspector();$('inspector-content').insertAdjacentHTML('afterbegin',`<p class="mode-caption">${esc(modeLabel())}</p>`);if(inspected.kind==='barrier'){const b=d.barriers.find(b=>b.id===inspected.id),r=d.repairs.find(r=>r.resolvesBarrierIds.includes(b.id)),path=d.paths.find(p=>p.barrierIds.includes(b.id));$('inspector-content').insertAdjacentHTML('afterbegin',`${photoHTML(b.photoFilename,true)}<p>Observed: ${esc(b.observedAt||'not field-surveyed')}<br>Measurement: ${esc(b.measurement||'not recorded')}</p>`);$('inspector-content').insertAdjacentHTML('beforeend',`<pre class="tags">${esc(JSON.stringify(path?.tags||b.tags||{},null,2))}</pre><button id="barrier-impact" ${r?'':'disabled'}>What does fixing this unlock?</button><p id="barrier-impact-result" class="hint"></p>`);if(r)$('barrier-impact').onclick=async()=>{const revision=state.revision,id=b.id,ids=p?.repairIds||[],without=ids.filter(x=>x!==r.id),withRepair=[...new Set([...ids,r.id])];try{const[before,after]=await Promise.all([client.request('evaluate',d,without),client.request('evaluate',d,withRepair)]);if(revision!==state.revision||inspected?.id!==id)return;$('barrier-impact-result').textContent=`${after.connectedCount-before.connectedCount} additional destination pairs with this repair, keeping the other repairs in view fixed. ${modeLabel()}. Counterfactual ignores budget; repairing an unknown path does not certify it.`;}catch(e){if(e.message!=='Cancelled')notify(e.message);}};}if(inspected.kind==='node'&&d.imported){const n=d.nodes.find(n=>n.id===inspected.id);$('inspector-content').querySelector('h3').textContent=n.label||'Unnamed graph point';$('inspector-content').insertAdjacentHTML('afterbegin',badge(n.labelProvenance||n.provenance));$('inspector-content').insertAdjacentHTML('beforeend',`<label for="destination-name">Survey / planning destination name</label><input id="destination-name" value="${esc(n.label)}" maxlength="80"><button id="save-destination-name">Save name</button><p class="hint">Planner-provided label; does not certify accessibility.</p>`);$('save-destination-name').onclick=()=>{const name=$('destination-name').value.trim();if(!name)return notify('Enter a human-readable name');const raw=v5raw.get(d.id).nodes.find(x=>x.id===n.id);raw.label=name;raw.labelProvenance='hypothetical';reloadEvidence();};}return;}
 $('inspector-title').textContent=state.view==='manual'?'Your repair plan':state.plan?'Repair plan':'Evidence first';const ids=p?.repairIds||[];$('inspector-content').innerHTML=`<p class="mode-caption">${esc(modeLabel())}</p>${state.plan||state.view==='manual'?`<h3>${ids.length} repairs · ${money(p.totalCost)} illustrative</h3><p>${applying?'Applying computed repair sequence.':state.view!=='recommended'?'Selected simulation view.':state.plan.optimal?'Proven optimal within this model.':'Best found within the search limit.'} The strip below shows the destination-pair gain.</p><ol>${ids.map(id=>{const r=d.repairs.find(r=>r.id===id),b=d.barriers.find(b=>b.id===r.resolvesBarrierIds[0]);return`<li><button data-inspect="${esc(b.id)}" class="repair-row">${photoHTML(b.photoFilename)}<span>${esc(b.title)}<small>${esc(b.observedAt||'No field date')}<br>${badge(b.provenance)} ${badge(r.provenance)}<br>${money(r.cost)} illustrative</small></span></button></li>`;}).join('')}</ol>${ids.length||applying?'':'<p>No repairs in this view. Missing evidence is not proof of access.</p>'}`:`<div class="eyebrow">FROM OBSERVATION TO DECISION</div><h3>A few repairs.<br>More connections.</h3><p>Record barriers and confirm step-free stretches. Then find which combination reconnects the most destination pairs.</p><p>${d.source&&!d.isHypothetical?`${d.surveyObservations?.length||0} survey observations loaded. Strict mode may honestly show zero until evidence arrives.`:'This is a labelled demonstration scenario.'}</p><button id="open-survey">Add survey evidence</button>`}`;for(const el of $('inspector-content').querySelectorAll('[data-inspect]'))el.onclick=()=>inspectBarrier(el.dataset.inspect);if($('open-survey'))$('open-survey').onclick=()=>{$('advanced').open=true;switchTab('import');$('advanced').scrollIntoView();};};
const oldPOIs=renderPOIs;renderPOIs=function(){oldPOIs();for(const button of $('poi-results').querySelectorAll('[data-dest]')){const n=state.data.nodes.find(n=>n.id===button.dataset.dest);if(n&&!n.label)button.textContent='Unnamed graph point · inspect to name';}};
toggleDestination=function(id){const d=v5raw.get(state.data.id),n=d.nodes.find(n=>n.id===id);if(!n.label){inspectPoint(id);notify('Name this destination before adding it');return;}const ids=state.data.nodes.filter(n=>n.kind==='destination').map(n=>n.id);try{DAImporter.destinations(d,ids.includes(id)?ids.filter(x=>x!==id):[...ids,id]);reloadEvidence();}catch(e){notify(e.message);}};
async function compareModes(){if(!state.data.source||state.data.isHypothetical)return;cancel();let l;try{l=limits();}catch(e){return notify(e.message);}const revision=state.revision,raw=v5raw.get(state.data.id);setBusy(true);try{const[strict,assumed]=await Promise.all(['strict','assumed'].map(mode=>client.request('optimize',mergedArea(raw.id,mode),l.limit,l.cost)));if(state.revision!==revision)return;modeComparison={strict,assumed};$('advanced').open=true;switchTab('compare');render();$('mode-comparison').scrollIntoView();}catch(e){if(e.message!=='Cancelled')notify(e.message);}finally{if(state.revision===revision)setBusy(false);}}
fetchArea=async function(refresh=false){if(importController){importController.abort();return;}let box;try{box=refresh?state.data.source.bounds:boxInputs();DAImporter.bounds(box);}catch(e){return notify(e.message);}const revision=state.revision,old=v5raw.get(state.data.id),controller=new AbortController();importController=controller;$('fetch-area').textContent='Cancel import';try{const result=await DANetwork.get(box,{refresh,offline:offlineMode||!navigator.onLine,signal:controller.signal,onStatus:t=>$('import-status').textContent=t});const data=await client.request('import',result.raw,box,{retrieved:result.retrieved,id:refresh?old.id:undefined,name:refresh?old.name:undefined});if(controller.signal.aborted||revision!==state.revision)throw new Error('Import cancelled because controls changed');data.source.community={lastUpdated:result.raw.elements.map(e=>e.timestamp).filter(Boolean).sort().at(-1)||null,editCount:null};if(refresh){for(const n of data.nodes){const prior=old.nodes.find(x=>x.id===n.id);if(prior?.label){n.label=prior.label;n.labelProvenance=prior.labelProvenance;}}DAImporter.destinations(data,old.nodes.filter(n=>n.kind==='destination'&&data.nodes.some(x=>x.id===n.id)).map(n=>n.id));}cleanNames(data);v5raw.set(data.id,data);rebuildAreas();importController=null;loadArea(data.id);$('import-status').textContent=result.warning||`${result.cached?'Cached':'Imported'} ${data.nodes.length} junctions / ${data.paths.length} segments. Select and name destinations on the map.`;try{await DACache.put('v5-area:'+data.id,data);}catch{}}catch(e){$('import-status').textContent=e.message+' · Current snapshot preserved.';}finally{importController=null;$('fetch-area').textContent='Fetch OSM evidence';}};
function reducedMotion(){return !!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;}
async function applyPlan(){const recommendation=state.plan?.recommended,origin=$('apply-origin').value;if(!recommendation)return;if(!origin){notify('Choose a flood origin first');return;}swipeEnabled=false;closeSwipe();cancel();const token=state.revision,data=state.data;applying={token};setBusy(true);$('progress-text').textContent='Applying computed repair sequence…';state.view='manual';state.manualIds=[];state.manual=state.baseline;state.reach=null;render();const valid=()=>applying?.token===token&&state.revision===token;try{for(let i=0;i<recommendation.repairIds.length;i++){const ids=recommendation.repairIds.slice(0,i+1),step=await client.request('evaluate',data,ids);if(!valid())return;state.manualIds=ids;state.manual=step;render();if(!reducedMotion())await new Promise(resolve=>setTimeout(resolve,320));}const distance=Number($('reach-distance').value)||500,steps=reducedMotion()?[distance]:[.2,.4,.6,.8,1].map(t=>t*distance);const before=await client.request('isochrone',data,[],origin,distance);for(const radius of steps){const after=await client.request('isochrone',data,recommendation.repairIds,origin,radius);if(!valid())return;state.reach={before,after,view:'recommended',show:'after'};render();if(!reducedMotion())await new Promise(resolve=>setTimeout(resolve,150));}if(valid()){state.view='recommended';$('progress-text').textContent='Plan applied · simulation';notify(`Plan applied in simulation. Flood shows ${distance} metres from the chosen destination.`);}}catch(e){if(e.message!=='Cancelled')notify(e.message);}finally{if(valid()){applying=null;setBusy(false);render();}}}
async function presentNext(){if(presentationBusy)return;presentationBusy=true;const revision=state.revision;try{presentationStep=(presentationStep+1)%6;$('present-status').textContent=`Present ${presentationStep+1}/6 · → next · change controls to reset`;if(presentationStep===0){setView('current');if(state.data.barriers[0])inspectBarrier(state.data.barriers[0].id);else notify('No field barrier yet. Add your survey, or choose the synthetic fixture for rehearsal.');}else if(presentationStep===1){let l=limits();const options=state.data.repairs.filter(r=>(l.cost===null||r.cost<=l.cost)&&l.limit>0);const scores=await Promise.all(options.map(r=>client.request('evaluate',state.data,[r.id])));if(revision!==state.revision)return;scores.sort((a,b)=>a.connectedCount-b.connectedCount||a.totalCost-b.totalCost);const weak=scores[0]||state.baseline;state.manual=weak;state.manualIds=weak.repairIds;state.view='manual';render();notify('Computed weak single-repair plan under the current limits.');}else if(presentationStep===2)await calculate();else if(presentationStep===3){if(!$('apply-origin').value){$('reach-origin').value=state.data.nodes.find(n=>n.kind==='destination')?.id||'';render();}await applyPlan();}else if(presentationStep===4){const b=state.data.barriers.find(b=>photoURL(b.photoFilename))||state.data.barriers[0];if(b)inspectBarrier(b.id);else notify('No surveyed barrier photo yet.');}else{$('greedy-main').scrollIntoView();notify(state.plan?`Greedy +${state.plan.greedy.newlyConnectedJourneyIds.length}; ${state.plan.optimal?'optimal':'best found'} +${state.plan.recommended.newlyConnectedJourneyIds.length} destination pairs.`:'Calculate a plan first.');}}catch(e){notify(e.message);}finally{presentationBusy=false;}}
function setupV5(){document.body.classList.add('v5');document.querySelector('.top-actions .badge').textContent='LOCAL / V5';const advanced=document.createElement('details');advanced.id='advanced';advanced.innerHTML='<summary>Advanced analysis <span>Compare · Connections · Evidence · Repair credit · Trade-offs · Reachability · Fragility · Import</span></summary>';const analysis=document.querySelector('.analysis');analysis.before(advanced);advanced.append(analysis);const profile=$('profile').closest('.wide');profile.hidden=true;profile.insertAdjacentHTML('afterend','<div class="wide"><label for="evidence-mode">Evidence mode</label><select id="evidence-mode"><option value="strict">Strict · recorded evidence only</option><option value="assumed">Assume unknown paths passable</option></select></div>');$('pane-compare').append(document.querySelector('.dock-actions'));const backupReset=$('reset-plan').onclick;const backupRestore=$('restore-data').onclick;$('reset-plan').onclick=()=>backupReset();$('restore-data').onclick=()=>{const original=state.data.id==='fatehpur-survey'?DASurveyArea:originalAreas.find(d=>d.id===state.data.id);if(original){scenarioEdits.delete(original.id);localStorage.setItem('disabledaccess-v5-scenarios',JSON.stringify([...scenarioEdits.values()]));v5raw.set(original.id,structuredClone(original));reloadEvidence();}else backupRestore();};$('area-provenance').hidden=true;document.querySelector('.control-dock h1').innerHTML='What should we<br>repair first?';document.querySelector('.map-title').insertAdjacentHTML('beforeend','<p id="mode-banner"></p><p id="retrieval"></p><p id="map-status"></p>');document.querySelector('.top-actions').insertAdjacentHTML('beforeend','<button id="refresh-osm">Refresh from OSM</button><button id="present">Present →</button><span id="present-status" aria-live="polite"></span>');const story=document.createElement('div');story.className='story-actions';story.innerHTML='<label for="apply-origin">Reachability flood from</label><select id="apply-origin"><option value="">Choose flood origin</option></select><button id="apply-plan">Apply plan</button><button id="swipe-toggle" aria-pressed="false">Before / after swipe</button><button id="compare-modes">Compare modes</button><p id="greedy-main"></p>';document.querySelector('.stage').append(story);$('pane-compare').insertAdjacentHTML('afterbegin','<div id="mode-comparison"></div>');$('overpass-server').hidden=true;document.querySelector('label[for="overpass-server"]').textContent='Automatic mirrors: Private.coffee → overpass-api.de (30-second timeout each)';setupSurveyUI();$('pane-import').insertAdjacentHTML('beforeend','<label for="basemap-source">Basemap source</label><select id="basemap-source"><option value="auto">Automatic: OpenFreeMap → OpenStreetMap</option><option value="osm">OpenStreetMap raster (keyless fallback)</option></select>');$('basemap-source').onchange=()=>{mapProvider=$('basemap-source').value==='osm'?1:0;window.DABasemapStyle=mapProvider?fallbackStyle:primaryStyle;closeSwipe();if(geoMap)geoMap.remove();geoMap=null;geoReady=false;geoArea=null;observedMap=null;renderer='geo';$('geo-map').hidden=false;$('svg-map').hidden=true;renderGeo(true);render();};for(const pane of document.querySelectorAll('.analysis-pane'))pane.insertAdjacentHTML('afterbegin','<p class="analysis-mode mode-caption"></p>');$('evidence-mode').onchange=()=>{evidenceMode=$('evidence-mode').value;reloadEvidence();};$('area').onchange=e=>loadArea(e.target.value);$('compare-modes').onclick=compareModes;$('refresh-osm').onclick=()=>{if(!state.data.source)return notify('Choose a real geography area first');$('advanced').open=true;switchTab('import');return fetchArea(true);};$('fetch-area').onclick=()=>fetchArea(false);$('calculate').onclick=calculate;$('apply-origin').onchange=()=>{$('reach-origin').value=$('apply-origin').value;};$('apply-plan').onclick=applyPlan;$('swipe-toggle').onclick=()=>{swipeEnabled=!swipeEnabled;$('swipe-toggle').setAttribute('aria-pressed',String(swipeEnabled));if(swipeEnabled)renderSwipe();else closeSwipe();};$('present').onclick=presentNext;window.addEventListener('keydown',e=>{if(e.key==='ArrowRight'&&presentationStep>=0&&!/INPUT|SELECT|TEXTAREA/.test(e.target?.tagName)){e.preventDefault();presentNext();}});$('import-open').textContent='Survey & import';$('import-open').onclick=()=>{advanced.open=true;switchTab('import');advanced.scrollIntoView();};const origTab=switchTab;switchTab=function(name){advanced.open=true;origTab(name);};rebuildAreas();loadArea('fatehpur-survey');for(const[id,d]of v5raw)if(d.source)DACache.get('survey:'+id).then(async overlay=>{if(!overlay)return;const bundled=surveyOverlay(id);if(bundled&&Date.parse(bundled.updatedAt||'')>Date.parse(overlay.updatedAt||'1970-01-01'))return;DASurvey.validate(overlay);surveyOverlays.set(id,overlay);for(const p of overlay.photos){try{const blob=await DACache.get('photo:'+p.id);if(blob)surveyURLs.set(p.id,URL.createObjectURL(blob));}catch{}}if(state.data.id===id)reloadEvidence();}).catch(()=>{});}
setupV5();
